INSERT INTO TemaRedacao (titulo, proposta, textos_apoio, expectativa_banca, genero, ano, origem, fonte_descricao, fonte_url, vestibular_id) VALUES (N'Desafios para a valorização da herança africana no Brasil', N'A partir da leitura dos textos motivadores e com base nos conhecimentos construídos ao longo de sua formação, redija texto dissertativo-argumentativo em modalidade escrita formal da língua portuguesa sobre o tema "Desafios para a valorização da herança africana no Brasil", apresentando proposta de intervenção que respeite os direitos humanos. Selecione, organize e relacione, de forma coerente e coesa, argumentos e fatos para defesa de seu ponto de vista.', N'Os textos motivadores oficiais estão no caderno de prova do INEP (link da fonte).', N'Critérios oficiais do INEP (Cartilha do Participante - A redação no Enem): C1 domínio da modalidade escrita formal; C2 compreensão da proposta e aplicação de conceitos de várias áreas dentro do tipo dissertativo-argumentativo, sem tangenciar o tema; C3 seleção, relação, organização e interpretação de informações em defesa de um ponto de vista (projeto de texto); C4 conhecimento dos mecanismos linguísticos para a argumentação (coesão); C5 proposta de intervenção detalhada (agente, ação, meio/modo, efeito e detalhamento) que respeite os direitos humanos. Cada competência vale de 0 a 200 pontos (níveis 0, 40, 80, 120, 160 e 200). Fuga total ao tema, texto com até 7 linhas, outro tipo textual ou desrespeito aos direitos humanos (no ENEM atual, este último zera apenas C5) levam a penalidades previstas na cartilha.', N'Dissertativo-argumentativo', 2024, 'OFICIAL', N'INEP - Prova de redação do ENEM 2024', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'));
